import React, { useState, useEffect } from 'react';
import { Modal, Button, Form } from 'react-bootstrap';

function ProductsList() {
  const [products, setProducts] = useState([]); 
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Para el modal
  const [showModal, setShowModal] = useState(false);
  const [currentProduct, setCurrentProduct] = useState(null);
  const [formData, setFormData] = useState({ nom: '', referencia: '', descripcio: '', quantitat: '' });

  // Obtener productos
  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    setLoading(true);
    try {
      const res = await fetch('http://localhost/api/productes');
      if (!res.ok) throw new Error('Error al obtener productos');
      const data = await res.json();
      setProducts(data.dades || []);
    } catch (err) {
      console.error('Error fetching products:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  // Abrir modal para editar
  const handleEdit = (product) => {
    setCurrentProduct(product);
    setFormData({
      nom: product.nom,
      referencia: product.referencia,
      descripcio: product.descripcio,
      quantitat: product.quantitat,
    });
    setShowModal(true);
  };

  // Guardar cambios del producto
  const handleSave = async () => {
    try {
      const res = await fetch(`http://localhost/api/productes/${currentProduct.id}`, {
        method: 'PUT',
        headers: { 
          'Content-Type': 'application/json',
          'Accept': 'application/json',
              'Authorization': `Bearer ${token}` // ⚡ importante

        },
        body: JSON.stringify(formData),
      });
      if (!res.ok) throw new Error('Error al actualizar producto');
      // Actualizar listado local
      setProducts(products.map(p => (p.id === currentProduct.id ? { ...p, ...formData } : p)));
      setShowModal(false);
    } catch (err) {
      console.error(err);
      alert('Error al guardar cambios');
    }
  };

  // Eliminar producto
  const handleDelete = async (id) => {
    if (!window.confirm('Estàs segur que vols eliminar aquest producte?')) return;
    try {
      const res = await fetch(`http://localhost/api/productes/${id}`, {
        method: 'DELETE',
        headers: { Accept: 'application/json' },
      });
      if (!res.ok) throw new Error('Error al eliminar producto');
      setProducts(products.filter(p => p.id !== id));
    } catch (err) {
      console.error(err);
      alert('Error al eliminar el producto');
    }
  };

  if (loading) return <p>Cargando productos...</p>;
  if (error) return <p>Error: {error}</p>;
  if (products.length === 0) return <p>No hay productos disponibles.</p>;

  return (
    <>
      <div className="row">
        {products.map(product => (
          <div key={product.id} className="col-md-4 mb-3">
            <div className="card h-100">
              <div className="card-body">
                <h5 className="card-title">{product.nom}</h5>
                <p className="card-text">{product.descripcio}</p>
                <p className="card-text"><strong>Referencia:</strong> {product.referencia}</p>
                <p className="card-text"><strong>Cantidad:</strong> {product.quantitat}</p>
                <Button variant="warning" size="sm" onClick={() => handleEdit(product)} className="me-2">
                  Editar
                </Button>
                <Button variant="danger" size="sm" onClick={() => handleDelete(product.id)}>
                  Eliminar
                </Button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Modal de edición */}
      <Modal show={showModal} onHide={() => setShowModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Editar producto</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form>
            <Form.Group className="mb-3">
              <Form.Label>Nombre</Form.Label>
              <Form.Control
                type="text"
                value={formData.nom}
                onChange={e => setFormData({ ...formData, nom: e.target.value })}
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Referencia</Form.Label>
              <Form.Control
                type="text"
                value={formData.referencia}
                onChange={e => setFormData({ ...formData, referencia: e.target.value })}
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Descripción</Form.Label>
              <Form.Control
                type="text"
                value={formData.descripcio}
                onChange={e => setFormData({ ...formData, descripcio: e.target.value })}
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Cantidad</Form.Label>
              <Form.Control
                type="number"
                value={formData.quantitat}
                onChange={e => setFormData({ ...formData, quantitat: e.target.value })}
              />
            </Form.Group>
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            Cancel·lar
          </Button>
          <Button variant="primary" onClick={handleSave}>
            Guardar
          </Button>
        </Modal.Footer>
      </Modal>
    </>
  );
}

export default ProductsList;
